                    throws IOException {
                gen.writeString(OUTPUT_FORMAT.format(value));
            }
        });
        module.addDeserializer(OffsetDateTime.class, new JsonDeserializer<>() {
            @Override
            public OffsetDateTime deserialize(JsonParser parser, DeserializationContext context)
                    throws IOException {
