Window registration:
```java
@Transactional
public SponsorWindowResponse createSponsorWindow(CreateSponsorWindowRequest request) {
    String windowKey = blank ? UUID : request.windowKey();
    String hash = sha256(OP_CREATE_WINDOW + "|" + windowKey + "|" + sponsorKey + "|" + businessDay + "|" + canonicalChannels + "|" + startMs + "|" + endMs);
    return idempotent(request.requestId(), OP_CREATE_WINDOW, hash, SponsorWindowResponse.class, () -> {
        validateWindowParams(...); // 422 checks
        // channels exist → 404
        // lock channels sorted
        List<String> channels = sortedDistinct(request.channels());
        for (ch : channels) { repo.findChannel(ch).orElseThrow(404); }
        for (ch : channels) repo.lockChannelForUpdate(ch);
        if (repo.findLatestWindow(windowKey).isPresent()) throw conflict("DUPLICATE_WINDOW_KEY", ...);
        // overlap check per channel
        for (ch : channels) {
            List<SponsorWindowRow> overlaps = repo.findActiveOverlappingWindows(sponsorKey, ch, startMs, endMs, null);
            if (!overlaps.isEmpty()) throw unprocessable("WINDOW_OVERLAP", ...);
        }
        long id = repo.insertWindow(windowKey, 1, sponsorKey, businessDay, startMs, endMs, nowMs());
        for (ch : channels) repo.insertWindowChannel(id, ch);
        return toWindowResponse(...);
    });
}
```

