                            toMs(request.end()), null);
                    long id = repo.insertWindow(windowKey, 1, request.sponsorKey(),
                            request.businessDay(), toMs(request.start()), toMs(request.end()),
                            nowMs());
                    for (String channelId : channels) {
                        repo.insertWindowChannel(id, channelId);
                    }
